items.gold_sql:
SELECT order_id,payment_sequential,payment_installments
FROM order_payments WHERE payment_installments IS NOT NULL
ORDER BY payment_installments DESC,order_id,payment_sequential LIMIT 1;

SELECT ROUND(AVG(cnt),2) FROM (
 SELECT o.order_id,COUNT(oi.order_item_id) AS cnt
 FROM orders o LEFT JOIN order_items oi ON oi.order_id=o.order_id
 GROUP BY o.order_id
) t;

SELECT c.customer_state,COUNT(*) AS cnt FROM orders o
JOIN customers c ON c.customer_id=o.customer_id
GROUP BY c.customer_state HAVING COUNT(*)>5000 ORDER BY cnt DESC;

SELECT DATE_TRUNC('month', order_purchase_timestamp) AS month,
       COUNT(*) AS cnt
FROM orders GROUP BY 1 ORDER BY 1;

WITH monthly AS (
 SELECT DATE_TRUNC('month',order_purchase_timestamp) AS m,COUNT(*) AS cnt
 FROM orders GROUP BY 1
), calendar AS (
 SELECT generate_series(MIN(m),MAX(m),INTERVAL '1 month') AS m FROM monthly
), filled AS (
 SELECT c.m,COALESCE(m.cnt,0) AS cnt FROM calendar c LEFT JOIN monthly m ON m.m=c.m
)
SELECT m AS month,cnt,cnt-LAG(cnt) OVER(ORDER BY m) AS mom_change FROM filled ORDER BY m;

SELECT DATE_TRUNC('month', period_start) AS month,
       ROUND(SUM(commission), 2) AS total
FROM settlements GROUP BY 1 ORDER BY 1;

SELECT s.seller_state, ROUND(SUM(oi.price), 2) AS sales
FROM order_items oi JOIN sellers s ON s.seller_id = oi.seller_id
GROUP BY 1 ORDER BY sales DESC;

SELECT o.order_status,ROUND(AVG(r.review_score),2) AS avg_score
FROM orders o LEFT JOIN order_reviews r ON r.order_id=o.order_id
GROUP BY o.order_status ORDER BY avg_score DESC NULLS LAST;

SELECT s.seller_state,ROUND(SUM(st.net_amount),2) AS net
FROM settlements st LEFT JOIN sellers s ON s.seller_id=st.seller_id
GROUP BY s.seller_state ORDER BY net DESC NULLS LAST;

SELECT p.product_id, p.product_photos_qty, COUNT(*) AS sold
FROM order_items oi JOIN products p ON p.product_id = oi.product_id
GROUP BY 1, 2 ORDER BY sold DESC NULLS LAST,p.product_id LIMIT 10;

WITH valid_orders AS (
 SELECT o.order_id,c.customer_unique_id FROM orders o JOIN customers c ON c.customer_id=o.customer_id
 WHERE o.order_status NOT IN ('canceled','unavailable')
), item_totals AS (
 SELECT order_id,SUM(price+freight_value) AS gmv FROM order_items GROUP BY order_id
)
SELECT COUNT(*) AS valid_orders,COUNT(DISTINCT vo.customer_unique_id) AS buyers,
 ROUND(SUM(it.gmv)/NULLIF(COUNT(*),0),2) AS aov
FROM valid_orders vo LEFT JOIN item_totals it ON it.order_id=vo.order_id;

SELECT ROUND(100.0*COUNT(*) FILTER(
 WHERE order_delivered_customer_date<=order_estimated_delivery_date
)/NULLIF(COUNT(*),0),2) AS on_time_pct
FROM orders WHERE order_delivered_customer_date IS NOT NULL;

WITH sold AS (
 SELECT COUNT(DISTINCT oi.product_id) AS n FROM order_items oi
 JOIN orders o ON o.order_id=oi.order_id WHERE o.order_status NOT IN ('canceled','unavailable')
), allp AS(SELECT COUNT(*) AS n FROM products)
SELECT ROUND(100.0*s.n/NULLIF(a.n,0),2) AS sell_through_pct FROM sold s CROSS JOIN allp a;

WITH coupon_totals AS (
 SELECT order_id,SUM(discount_amount) AS discount_amount FROM coupon_usages GROUP BY order_id
), order_totals AS (
 SELECT order_id,SUM(price+freight_value) AS order_gmv FROM order_items GROUP BY order_id
)
SELECT ROUND(SUM(ot.order_gmv),2) AS gmv,ROUND(SUM(ct.discount_amount),2) AS discount,
 ROUND(100.0*SUM(ct.discount_amount)/NULLIF(SUM(ot.order_gmv),0),2) AS discount_pct
FROM coupon_totals ct JOIN orders o ON o.order_id=ct.order_id
JOIN order_totals ot ON ot.order_id=ct.order_id
WHERE o.order_status NOT IN ('canceled','unavailable');

SELECT st.category_id,ROUND(100.0*COUNT(*) FILTER(
 WHERE st.resolved_at IS NOT NULL
 AND EXTRACT(EPOCH FROM(st.resolved_at-st.created_at))/3600.0<=tc.sla_hours
)/NULLIF(COUNT(*),0),2) AS sla_pct
FROM support_tickets st LEFT JOIN ticket_categories tc ON tc.category_id=st.category_id
GROUP BY st.category_id ORDER BY sla_pct;

SELECT ROUND(100.0*COUNT(*) FILTER(WHERE converted_at IS NOT NULL)/NULLIF(COUNT(*),0),2) AS conversion_pct,
 ROUND(SUM(reward_amount)/NULLIF(COUNT(*) FILTER(WHERE converted_at IS NOT NULL),0),2) AS reward_per_converted
FROM referrals;
